// Đã xuất hàng cho khách nhưng chưa lập hoá đơn — rủi ro thất thu: hàng đã ra khỏi kho mà
// chưa có chứng từ thu tiền tương ứng. Báo NỘI BỘ cho kế toán để rà lại trước khi khách
// quên hoặc khất nợ.
const d = $json;
const items = d.items || [];
const vnd = n => new Intl.NumberFormat('vi-VN').format(n || 0) + '₫';

const rows = items.map(v => `<tr><td>${v.voucher_no || '—'}</td><td>${new Date(v.voucher_date).toLocaleDateString('vi-VN')}</td><td>${v.partner_name}</td><td align="right">${vnd(v.total_amount)}</td></tr>`).join('');

const html = `<h2>⚠️ ${items.length} dòng đã xuất hàng nhưng chưa lập hoá đơn</h2>`
  + `<p>Tổng giá trị chưa lập hoá đơn: <b style="color:#c00">${vnd(d.total_amount)}</b>.</p>`
  + `<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">`
  + `<tr><th>Số chứng từ</th><th>Ngày</th><th>Khách hàng</th><th>Số tiền</th></tr>${rows}</table>`
  + `<p style="color:#888;font-size:12px">${d.company_name} — ${new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' })}</p>`;

return { json: {
  email_to: d.company_email || '',
  email_subject: `⚠️ ${items.length} dòng đã xuất hàng chưa lập HĐ — tổng ${vnd(d.total_amount)}`,
  email_html: html
} };
